    assert(pre.local_updates[rid].is_Init());
    assert(pre.combiner.contains_key(node_id));
    assert(pre.combiner[node_id].is_Placed());
    let queued_ops = pre.combiner[node_id].get_Placed_queued_ops();
    let op = pre.local_updates[rid].get_Init_op();
    assert(!queued_ops.contains(rid)) by {
        if queued_ops.contains(rid) {
            let j = choose|j: int| 0 <= j < queued_ops.len() && queued_ops.index(j) == rid;
            assert(0 <= j < queued_ops.len());
            assert(pre.local_updates.contains_key(queued_ops.index(j)));
            assert(pre.local_updates[queued_ops.index(j)].is_Placed());
            assert(pre.local_updates[queued_ops.index(j)] !== pre.local_updates[rid]);
        }
    };
    assert(pre.tail <= post.tail);
    assert(post.log === pre.log.insert(pre.tail, LogEntry { op, node_id }));
    assert(post.local_updates[rid] === UpdateState::Placed { op, idx: pre.tail });
    assert(post.combiner[node_id] === CombinerState::Placed { queued_ops: queued_ops.push(rid) });

    assert forall |n: NodeId| #[trigger] post.combiner.contains_key(n)
        implies post.wf_combiner_for_node_id(n) by {
        if n == node_id {
            LogRangeMatchesQueue_append(
                queued_ops, pre.log, post.log, 0,
                pre.local_versions[node_id], pre.tail, node_id,
                pre.local_updates, post.local_updates, rid,
                LogEntry { op, node_id },
            );
            assert(seq_unique(queued_ops.push(rid))) by {
                assert(seq_unique(queued_ops));
            }
        } else {
            assert(post.combiner[n] === pre.combiner[n]);
            match post.combiner[n] {
                CombinerState::Ready => {
                    LogRangeNoNodeId_append_other(
                        pre.log, post.log, pre.local_versions[n], pre.tail,
                        n, LogEntry { op, node_id },
                    );
                }
                CombinerState::Placed { queued_ops: q } => {
                    LogRangeMatchesQueue_append_other_augment(
                        q, pre.log, post.log, 0, pre.local_versions[n], pre.tail,
                        n, pre.local_updates, post.local_updates, rid,
                        LogEntry { op, node_id },
                    );
                }
                CombinerState::LoadedLocalVersion { queued_ops: q, lversion } => {
                    LogRangeMatchesQueue_append_other_augment(
                        q, pre.log, post.log, 0, lversion, pre.tail,
                        n, pre.local_updates, post.local_updates, rid,
                        LogEntry { op, node_id },
                    );
                }
                CombinerState::Loop { queued_ops: q, idx, lversion, tail } => {
                    LogRangeMatchesQueue_append_other_augment(
                        q, pre.log, post.log, idx, lversion, tail,
                        n, pre.local_updates, post.local_updates, rid,
                        LogEntry { op, node_id },
                    );
                }
                CombinerState::UpdatedVersion { queued_ops: q, tail } => {
                    LogRangeNoNodeId_append_other(
                        pre.log, post.log, tail, pre.tail,
                        n, LogEntry { op, node_id },
                    );
                }
            }
        }
    };
    assert(post.inv_read_results()) by {
        assert forall |r| #[trigger] post.local_reads.contains_key(r)
            implies post.read_results_match(post.local_reads[r]) by {
            assert(pre.local_reads.contains_key(r));
            assert(pre.read_results_match(pre.local_reads[r]));
            match post.local_reads[r] {
                ReadonlyState::Done { ret, version_upper_bound, op, .. } => {
                    let v = choose|v: nat| rangeincl(version_upper_bound, v, pre.version_upper_bound)
                        && ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op);
                    assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
                    compute_nrstate_at_version_preserves(pre.log, post.log, v);
                }
                _ => {}
            }
        }
    };
}

